pub fn numpy_insert<T>(mut arr: Vec<T>, idx: usize, value: T) -> Vec<T> {
    // We assume 0 <= idx <= arr.len()
    // Split off the tail starting at `idx`
    let mut tail = arr.split_off(idx);
    // Push the new value at position `idx`
    arr.push(value);
    // Append the old tail back on
    arr.append(&mut tail);
    arr
}

